/*<info serverAlias="DBRMS-bodb_RMS" isFunction="0" isNested="1"></info>*/
ALTER PROCEDURE [dbo].[Task_RMS_SumData_rmSumByLeague]
	@winlostdate	SMALLDATETIME
	,@ErrCode		INT = 0 OUTPUT
	,@ErrMsg		VARCHAR(4000) = '' OUTPUT
AS

/*
	Created: 20200601@Percy
	DB: DBRMS-bodb_RMS
	Task: RMS - Sum data of rmSumByLeague

	Revisions:
		- 20200601@Percy: Initialize SP [RedmineID: #130275]
		- 20210111@Danny: Enhance performance (get data from bettrans_bk) [RedmineID: #123157]
		- 20210607@Danny: Move 'Saba789' to Credit Site  [RedmineID: #153874]
		- 20220301@Danny: Support basketball Sport type data [RedmineID: #169072]
		- 20240315@Cherry: Enhance League Bettype report (#197684)
		- 20241030@Cherry: Add Single Match Parlay (#209293)
		- 20250212@Cherry: hot fix (#217757)
		- 20250214@Cherry: Support direct member (#215427)
		- 20251016@Cherry: Move sites NovaCasino, SEAL888 from Deposit to Credit (#241763)
		- 20251110@Cherry: Tuning SP

*/

BEGIN
	SET NOCOUNT ON

	DECLARE @WLDate DATE
	SELECT  @WLDate = @winlostdate
	
	DECLARE @MBBU TABLE (BalanceUpDay SMALLDATETIME, MoveBetsDay SMALLDATETIME)
	INSERT INTO @MBBU (BalanceUpDay, MoveBetsDay)
	EXEC bodb02.dbo.Age_SelBalanceUpDay

	DECLARE @BalanceUpDay SMALLDATETIME, @MoveBetsDay SMALLDATETIME
	SELECT  @BalanceUpDay = BalanceUpDay, @MoveBetsDay = MoveBetsDay FROM @MBBU

	IF @winlostdate < @BalanceUpDay
		RETURN

	CREATE TABLE #BettransmByLeague
	(
		transid				BIGINT 
		,leagueId			INT
		,matchid			INT
		,statusID			TINYINT
		,ParlayType			TINYINT
		,IsDeposit			BIT
		,stake				MONEY
		,winloss			MONEY
		,playercomm			MONEY
		,HouseWinloss		MONEY		
		,BetCount			INT
		,WonCount			INT
		,LoseCount			INT
		,DrawCount			INT
	)
	
	CREATE TABLE #rmSumByLeague
	(
		leagueId			INT
		,ParlayType			TINYINT
		,IsDeposit			BIT
		,BetCount			INT
		,WonCount			INT
		,LoseCount			INT
		,DrawCount			INT
		,MainBetCount		INT
		,MainWonCount		INT
		,MainLoseCount		INT
		,MainDrawCount		INT
		,MainStake			MONEY
		,MainTurnover		MONEY
		,MainTurnoverNoDraw	MONEY
		,MainMemberWinloss	MONEY
		,MainMemberComm		MONEY
		,MainHouseWinloss	MONEY
	)
	CREATE CLUSTERED INDEX CIX_rmSumByLeague ON #rmSumByLeague (leagueId, ParlayType)

	CREATE TABLE #bettrans (transid BIGINT, custid INT, refno BIGINT, ParlayType TINYINT, IsDeposit BIT, statusID TINYINT, TotalSelection SMALLMONEY, stake MONEY, winloss MONEY, playercomm MONEY, HouseWinloss MONEY)

	CREATE CLUSTERED INDEX CIX_bettran ON #bettrans (refno, custid)

	CREATE TABLE #bettransmbk (refno BIGINT, statusID TINYINT, leagueid INT)
	
	DECLARE @SQL VARCHAR(MAX)

	IF @winlostdate > @MoveBetsDay
	BEGIN
		INSERT INTO #bettrans (transid, custid, refno, ParlayType, IsDeposit, statusID, TotalSelection, stake, winloss, playercomm, HouseWinloss)
		SELECT transid, r.custid, refno, 
			CASE 
				WHEN betteam = N'1' THEN 2 --Mix Parlay
				ELSE 3 -- Combo Parlay
			END ParlayType, 
			CASE WHEN s.Site IN ('Saba789','NovaCasino','SEAL888') THEN 0 ELSE s.isDeposit END, statusID, hdp2,
			stake*actualrate, (winlost-actual_stake)*actualrate, playercomm*actualrate, 
		CASE WHEN tpositiontaking = 1 THEN 0 ELSE (-(winlost-actual_stake)*(1-tpositiontaking-CAST(ISNULL(epositiontaking, 0) AS DECIMAL(9,8)))-scomm+scomm*CAST(ISNULL(epositiontaking, 0) AS DECIMAL(9,8))/(1 - tpositiontaking))*actualrate END
		FROM dbo.rmBettrans r WITH (NOLOCK)
			INNER JOIN bodb02.dbo.Customer c WITH (NOLOCK) ON r.custid = c.custid
			INNER JOIN bodb02.dbo.Site s WITH (NOLOCK) ON c.site = s.site
		WHERE r.winlostdate = @winlostdate
			AND r.bettype = 29
			AND r.liveawayscore IN (1, 2, 3) -- soccer
			AND r.statusID IN (111, 112, 113, 101, 102)
			AND r.currency <> 20
	END
	ELSE
	BEGIN
		INSERT INTO #bettrans (transid, custid, refno, ParlayType, IsDeposit, statusID, TotalSelection, stake, winloss, playercomm, HouseWinloss)
		SELECT transid, r.custid, refno, 
			CASE 
				WHEN betteam = N'1' THEN 2 --Mix Parlay
				ELSE 3 -- Combo Parlay
			END ParlayType,
			CASE WHEN s.Site IN ('Saba789','NovaCasino','SEAL888') THEN 0 ELSE s.isDeposit END,
			statusID, hdp2, stake*actualrate, (winlost-actual_stake)*actualrate, playercomm*actualrate, 
		CASE WHEN tpositiontaking = 1 THEN 0 ELSE (-(winlost-actual_stake)*(1-tpositiontaking-CAST(ISNULL(epositiontaking, 0) AS DECIMAL(9,8)))-scomm+scomm*CAST(ISNULL(epositiontaking, 0) AS DECIMAL(9,8))/(1 - tpositiontaking))*actualrate END
		FROM dbo.rmBettrans_Old r WITH (NOLOCK)
			INNER JOIN bodb02.dbo.Customer c WITH (NOLOCK) ON r.custid = c.custid
			INNER JOIN bodb02.dbo.Site s WITH (NOLOCK) ON c.site = s.site
		WHERE r.winlostdate = @winlostdate
			AND r.bettype = 29
			AND r.liveawayscore IN (1, 2, 3) -- soccer
			AND r.statusID IN (111, 112, 113, 101, 102)
			AND r.currency <> 20
			AND r.transid NOT IN (SELECT transid FROM #bettrans)
	END

	INSERT INTO #BettransmByLeague (transid, leagueId, matchid, statusID, ParlayType, IsDeposit, stake, winloss, playercomm, HouseWinloss, BetCount, WonCount, LoseCount, DrawCount  )
	SELECT
		b.transid, 
		m.leagueid, 
		m.matchid,
		b.statusID, 
		b.ParlayType, 
		b.IsDeposit, 
		SUM(CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.stake/b.TotalSelection END), 
		SUM(CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.winloss/b.TotalSelection END),
		SUM(CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.playercomm/b.TotalSelection END), 
		SUM(CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.HouseWinloss/b.TotalSelection END), 		
		SUM(1), 
		SUM(CASE WHEN bm.statusID = 112 THEN 1 ELSE 0 END),
		SUM(CASE WHEN bm.statusID = 113 THEN 1 ELSE 0 END),
		SUM(CASE WHEN bm.statusID = 111 THEN 1 ELSE 0 END)
	FROM #bettrans b
		INNER JOIN dbo.rmBettransm_bk bm WITH (NOLOCK) ON b.refno = bm.refno
		INNER JOIN dbo.rmMatch_bk m WITH (NOLOCK) ON bm.matchid = m.matchid
	WHERE  m.sporttype IN (1,2) AND bm.winlostdate < @BalanceUpDay
	GROUP BY  b.transid, m.leagueid, m.matchid, b.ParlayType, b.IsDeposit, b.statusID

	INSERT INTO #BettransmByLeague (transid, leagueId, matchid, statusID, ParlayType, IsDeposit, stake, winloss, playercomm, HouseWinloss, BetCount, WonCount, LoseCount, DrawCount )
	SELECT
		b.transid, 
		m.leagueid, 
		m.matchid,
		b.statusID, 
		b.ParlayType, 
		b.IsDeposit, 
		SUM(CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.stake/b.TotalSelection END), 
		SUM(CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.winloss/b.TotalSelection END),
		SUM(CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.playercomm/b.TotalSelection END), 
		SUM(CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.HouseWinloss/b.TotalSelection END), 		
		SUM(1), 
		SUM(CASE WHEN bm.statusID = 112 THEN 1 ELSE 0 END),
		SUM(CASE WHEN bm.statusID = 113 THEN 1 ELSE 0 END),
		SUM(CASE WHEN bm.statusID = 111 THEN 1 ELSE 0 END)
	FROM #bettrans b
		INNER JOIN bodb02.dbo.bettransm bm WITH (NOLOCK) ON b.refno = bm.refno
		INNER JOIN bodb02.dbo.match m WITH (NOLOCK) ON bm.matchid = m.matchid
	WHERE  m.sporttype IN (1,2) AND (bm.winlostdate > @MoveBetsDay OR bm.winlostdate IS NULL)
	GROUP BY  b.transid, m.leagueid, m.matchid, b.ParlayType, b.IsDeposit, b.statusID


	INSERT INTO #BettransmByLeague (transid, leagueId, matchid, statusID, ParlayType, IsDeposit, stake, winloss, playercomm, HouseWinloss, BetCount, WonCount, LoseCount, DrawCount  )
	SELECT
		b.transid, 
		m.leagueid, 
		m.matchid,
		b.statusID, 
		b.ParlayType, 
		b.IsDeposit, 
		SUM(CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.stake/b.TotalSelection END), 
		SUM(CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.winloss/b.TotalSelection END),
		SUM(CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.playercomm/b.TotalSelection END), 
		SUM(CASE WHEN ISNULL(b.TotalSelection,0) = 0 THEN 0 ELSE b.HouseWinloss/b.TotalSelection END), 	
		SUM(1), 
		SUM(CASE WHEN bm.statusID = 112 THEN 1 ELSE 0 END),
		SUM(CASE WHEN bm.statusID = 113 THEN 1 ELSE 0 END),
		SUM(CASE WHEN bm.statusID = 111 THEN 1 ELSE 0 END)
	FROM #bettrans b
		INNER JOIN bodb02.dbo.bettransm14 bm WITH (NOLOCK) ON b.refno = bm.refno AND b.custid = bm.custid
		INNER JOIN bodb02.dbo.match14 m WITH (NOLOCK) ON bm.matchid = m.matchid
	WHERE m.sporttype IN (1,2)  AND bm.winlostdate BETWEEN @BalanceUpDay AND @MoveBetsDay
	GROUP BY  b.transid, m.leagueid, m.matchid, b.ParlayType, b.IsDeposit, b.statusID

	-- Single Match Parlay
	IF @winlostdate > @MoveBetsDay
	BEGIN
		INSERT INTO #BettransmByLeague (transid, leagueId, matchid, statusID, ParlayType, IsDeposit, stake, winloss, playercomm, HouseWinloss, BetCount, WonCount, LoseCount, DrawCount )
		SELECT
			r.transid, 
			m.leagueid, 
			m.matchid,
			r.statusID, 
			4 ParlayType, 
			CASE WHEN s.Site IN ('Saba789','NovaCasino','SEAL888') THEN 0 ELSE s.isDeposit END IsDeposit, 
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE r.stake * r.actualrate/r.hdp2 END), 
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE (r.winlost - r.actual_stake) * r.actualrate/r.hdp2 END),
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE r.playercomm * r.actualrate/r.hdp2 END), 
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE CASE WHEN r.tpositiontaking = 1 THEN 0 
				ELSE (-(r.winlost-r.actual_stake)*(1-r.tpositiontaking-CAST(ISNULL(r.epositiontaking, 0) AS DECIMAL(9,8)))-r.scomm+r.scomm*CAST(ISNULL(r.epositiontaking, 0) AS DECIMAL(9,8))/(1 - r.tpositiontaking))*r.actualrate END/r.hdp2 END), 	
			SUM(1), 
			SUM(CASE WHEN t.Result = 'Won' THEN 1 ELSE 0 END),
			SUM(CASE WHEN t.Result = 'Lose' THEN 1 ELSE 0 END),
			SUM(CASE WHEN t.Result = 'Draw' THEN 1 ELSE 0 END)
		FROM dbo.rmBettrans r WITH (NOLOCK)		
			INNER JOIN bodb02.dbo.match m WITH (NOLOCK) ON r.matchid = m.matchid
			INNER JOIN bodb02.dbo.SMP_MarketSelection t WITH(NOLOCK) ON t.MatchId = r.matchid AND t.MarketId = r.betcheck
			INNER JOIN bodb02.dbo.Customer c WITH (NOLOCK) ON r.custid = c.custid
			INNER JOIN bodb02.dbo.Site s WITH (NOLOCK) ON c.site = s.site
		WHERE r.bettype = 38
			AND r.winlostdate = @winlostdate
			AND r.statusID IN (111, 112, 113, 101, 102)
			AND r.currency <> 20
		GROUP BY r.transid, 
			m.leagueid, 
			m.matchid,
			r.statusID,
			CASE WHEN s.Site IN ('Saba789','NovaCasino','SEAL888') THEN 0 ELSE s.isDeposit END
	END

	IF @winlostdate BETWEEN @BalanceUpDay AND @MoveBetsDay
	BEGIN
		INSERT INTO #BettransmByLeague (transid, leagueId, matchid, statusID, ParlayType, IsDeposit, stake, winloss, playercomm, HouseWinloss, BetCount, WonCount, LoseCount, DrawCount )
		SELECT
			r.transid, 
			m.leagueid, 
			m.matchid,
			r.statusID, 
			4 ParlayType, 
			CASE WHEN s.Site IN ('Saba789','NovaCasino','SEAL888') THEN 0 ELSE s.isDeposit END IsDeposit, 
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE r.stake * r.actualrate/r.hdp2 END), 
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE (r.winlost - r.actual_stake) * r.actualrate/r.hdp2 END),
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE r.playercomm * r.actualrate/r.hdp2 END), 
			SUM(CASE WHEN ISNULL(r.hdp2,0) = 0 THEN 0 ELSE CASE WHEN r.tpositiontaking = 1 THEN 0 
				ELSE (-(r.winlost-r.actual_stake)*(1-r.tpositiontaking-CAST(ISNULL(r.epositiontaking, 0) AS DECIMAL(9,8)))-r.scomm+r.scomm*CAST(ISNULL(r.epositiontaking, 0) AS DECIMAL(9,8))/(1 - r.tpositiontaking))*r.actualrate END/r.hdp2 END), 	
			SUM(1), 
			SUM(CASE WHEN t.Result = 'Won' THEN 1 ELSE 0 END),
			SUM(CASE WHEN t.Result = 'Lose' THEN 1 ELSE 0 END),
			SUM(CASE WHEN t.Result = 'Draw' THEN 1 ELSE 0 END)
		FROM dbo.rmBettrans_Old r WITH (NOLOCK)		
			INNER JOIN bodb02.dbo.match14 m WITH (NOLOCK) ON r.matchid = m.matchid
			INNER JOIN bodb02.dbo.SMP_MarketSelection14 t WITH(NOLOCK) ON t.MatchId = r.matchid AND t.MarketId = r.betcheck
			INNER JOIN bodb02.dbo.Customer c WITH (NOLOCK) ON r.custid = c.custid
			INNER JOIN bodb02.dbo.Site s WITH (NOLOCK) ON c.site = s.site
		WHERE r.bettype = 38
			AND r.winlostdate = @winlostdate
			AND r.statusID IN (111, 112, 113, 101, 102)
			AND r.currency <> 20
		GROUP BY r.transid, 
			m.leagueid, 
			m.matchid,
			r.statusID,
			CASE WHEN s.Site IN ('Saba789','NovaCasino','SEAL888') THEN 0 ELSE s.isDeposit END
	END
		
	-- END SMP

	CREATE NONCLUSTERED INDEX idx_#BettransmByLeague ON #BettransmByLeague(leagueid, ParlayType, IsDeposit) INCLUDE (BetCount,WonCount, DrawCount,LoseCount)


	BEGIN TRY
	DELETE dbo.rmSumByLeague WITH (ROWLOCK, UPDLOCK) WHERE winlostdate = @WLDate

	INSERT INTO dbo.rmSumByLeague (winlostdate,leagueId,ParlayType,IsDeposit,BetCount,WonCount,DrawCount,LoseCount,MainBetCount,MainWonCount,MainLoseCount,MainDrawCount,MainStake,MainTurnover,MainTurnoverNoDraw,MainMemberWinloss,MainMemberComm,MainHouseWinloss)
	SELECT	@WLDate winlostdate
		,b.leagueid
		,b.ParlayType
		,b.IsDeposit
		,BetCount			= SUM(b.BetCount)
		,WonCount			= SUM(WonCount)
		,DrawCount			= SUM(DrawCount)
		,LoseCount			= SUM(LoseCount)
		,MainBetCount		= COUNT(1)
		,MainWonCount		= SUM(CASE WHEN b.statusID = 112 THEN 1 ELSE 0 END)
		,MainLoseCount		= SUM(CASE WHEN b.statusID = 113 THEN 1 ELSE 0 END)
		,MainDrawCount		= SUM(CASE WHEN b.statusID = 111 THEN 1 ELSE 0 END)
		,MainStake			= SUM(stake)
		,MainTurnover		= SUM(CASE WHEN b.statusID IN (111, 112, 113) THEN b.stake ELSE 0 END)
		,MainTurnoverNoDraw	= SUM(CASE WHEN b.statusID IN (112, 113) THEN b.stake ELSE 0 END)
		,MainWinloss		= SUM(b.winloss)
		,MainComm			= SUM(b.playercomm)
		,MainHouseWinloss	= SUM(b.HouseWinloss)
	FROM 
	(
		SELECT	b.leagueid
				,b.ParlayType
				,b.IsDeposit
				,b.transid
				,b.statusID
				,BetCount			= SUM(BetCount)
				,WonCount			= SUM(WonCount)
				,DrawCount			= SUM(DrawCount)
				,LoseCount			= SUM(LoseCount)
				,stake = SUM(b.stake)
				,winloss = SUM(b.winloss)
				,playercomm = SUM(b.playercomm)
				,HouseWinloss = SUM(b.HouseWinloss) 
			
		FROM #BettransmByLeague b
		GROUP BY b.transid, b.leagueid, b.ParlayType, b.IsDeposit, b.statusID
	) b
	GROUP BY
		b.leagueid, b.ParlayType, b.IsDeposit

	END TRY
	BEGIN CATCH
		SELECT @ErrCode = ERROR_NUMBER(), @ErrMsg = ERROR_MESSAGE()
		--RETURN
	END CATCH

	DROP TABLE #bettrans
	DROP TABLE #BettransmByLeague
	DROP TABLE #bettransmbk
	DROP TABLE #rmSumByLeague
END
